/** Instrument class a template has separate statistics for (GM drum map as used by GMD). */
export type GrooveClass = 'kick' | 'snare' | 'hihat' | 'other';

export const GROOVE_CLASSES: readonly GrooveClass[] = ['kick', 'snare', 'hihat', 'other'];

/** 16 values each: one per 16th step of a 4/4 bar. */
export interface GrooveCells {
  /** Mean timing offset from the STRAIGHT 16th grid, in fractions of a 16th (+ = late). Robust (10 % trimmed) mean. */
  offset: readonly number[];
  /** Spread of that timing (1.4826 × MAD), in fractions of a 16th. */
  spread: readonly number[];
  /** Relative velocity (accent) of a hit on this step; the hit-probability-weighted mean is 1. */
  vel: readonly number[];
  /** Probability (0..1) that a bar has a hit on this step. */
  prob: readonly number[];
  /** Hits measured on this step. Cells with too few hits use a fallback (see the extractor). */
  n: readonly number[];
}

export interface GrooveTemplate {
  id: string;
  label: string;
  /** GMD style labels merged into this template ("funk/groove", "neworleans/secondline"…). */
  styles: readonly string[];
  /** 4/4 beat performances measured. */
  performances: number;
  drummers: number;
  bars: number;
  /** Tempo of the measured performances: [min, median, max]. */
  bpm: readonly [number, number, number];
  /** Position of the off-beat 8th within the beat: 0.5 = straight, 0.667 = triplet shuffle. */
  swing8: number;
  /** Position of the 2nd 16th within its 8th: 0.5 = straight, 0.667 = triplet. */
  swing16: number;
  classes: Readonly<Record<GrooveClass, GrooveCells>>;
}
